  "和终端的 /login 一样，凭据由 pi 写进 ~/.pi/agent/auth.json，网页只转达提示、不保存也不回显密钥。OAuth 的回调落在运行 bridge 的这台电脑上；在别的设备上登录时，按提示把浏览器最后跳转到的网址粘贴回来。": "Same as /login in the terminal: pi writes the credentials to ~/.pi/agent/auth.json; the web page only relays the prompts and never stores or echoes the secret. The OAuth callback lands on the machine running the bridge; when signing in from another device, paste back the URL the browser ends up on.",
  "和终端相比少两样：不能让模型写摘要，报告里也不列出加载的扩展（网页这边拿不到运行中的会话对象）。": "Two things less than the terminal: the model cannot write the summary, and the report does not list loaded extensions (the web side cannot reach the live session object).",
