  "把「重讲」发出去：先提供上下文，再用简体技术中文说明。": "Send “Re-pitch”: give the context first, then explain it in Simplified Technical English.",
  "等一下。我不明白你在这里进行到哪一步。请重新说明。先提供上下文。然后使用简体技术中文来说明。": "Wait. I do not understand where you are in this. Explain it again. Give the context first. Then explain it in Simplified Technical English.",
