  "长用户消息收成卡片": "Fold long user messages into a card",
  "默认开。占满一屏的粘贴收成一张卡（长消息 · 多少行 · 多少字），点一下在卡里铺开；关掉退回原来露 240px 的折叠": "On by default. A paste that fills the screen becomes one card (Long message · lines · chars); tap it to open inside the card. Off goes back to the old 240px fold.",
  "长回答收成卡片": "Fold long answers into a card",
  "默认关。管的是 AI 的正文：同样先收成卡，点开在卡里读；关着用回答右上那颗折叠钮": "Off by default. Same card for the model's prose; tap to read inside the card. Off uses the fold button at the top right of the answer.",
