  "这一轮结束后再重新加载": "Reload after this turn finishes",
  "这个 MCP 服务要用到密钥，mcp.json 里只写了变量引用。请在系统环境变量里设置：{p1}，然后重启 bridge（或至少重新加载会话）。": "This MCP server needs a secret, and mcp.json only holds a variable reference. Set it in your system environment variables: {p1}, then restart bridge (or at least reload the session).",
  "这个会话来自磁盘（只读预览）。发消息会自动接管；终端里如果有 pi 在写同一个文件，先退出那边。": "This session comes from disk (read-only preview). Sending a message takes over automatically; if pi is writing the same file in a terminal, quit that first.",
