  "这个地址拿不到剪贴板（http 的局域网地址浏览器不给），可以用回复右上角的 ⧉。": "Clipboard isn't available at this address (the browser won't allow it on http LAN addresses); use ⧉ at the top right of the reply.",
  "这个文件在你编辑期间被改过了（可能是 pi 写的）": "This file changed while you were editing it (pi may have written it)",
  "这个浏览器/地址不支持 Web Push（iOS 需要先「添加到主屏幕」）": "This browser/address doesn't support Web Push (on iOS, add to home screen first)",
  "这个目录有 pi 的项目配置（.pi/ 下的设置、扩展、技能或 MCP）。网页里的 pi 不能弹信任提示，所以没有加载它们。": "This directory has pi project config (settings, extensions, skills or MCP under .pi/). pi in the web client can't show a trust prompt, so they weren't loaded.",
