  "不释放": "never",
  "分钟": "minutes",
  "内存水位": "Memory watermark",
  "保存阈值": "Save thresholds",
  "空闲与归档的阈值下一个 tick 就生效；内存水位等下一次采样（60 秒一次）。三个值都写进桥的状态目录，重启桥也还在。归档后释放写 0 就是不释放。": "The idle and archive thresholds apply from the next tick; the watermark waits for the next sample (once a minute). All three are written into the bridge's state directory, so restarting the bridge keeps them. Write 0 for the archive threshold to never release.",
  "已保存：空闲阈值下一个 tick 就生效，不用重启桥。": "Saved: the idle threshold applies from the next tick — no bridge restart needed.",
  "没有保存：空闲与水位必须是大于 0 的数；归档后释放可以是 0（不释放）。": "Not saved: the idle and watermark thresholds have to be numbers greater than 0; the archive threshold may be 0 (never release).",
  "全部休眠": "Sleep all",
  "把所有空闲的会话休眠掉：消息都在，下一条消息唤醒；正在跑的一轮不动。": "Put every idle session to sleep: messages stay, the next message wakes it. A run in flight is left alone.",
