  "输入你的要求，例如：判断该切到 main 还是先合并，别直接动 git": "Describe your request, e.g. decide whether to switch to main or merge first; don't touch git yet",
  "绕法已应用：下一次压缩起生效，不用重启": "Workaround applied: takes effect from the next compression, no restart needed",
  "绕法已撤销，回到 billion-context 的默认": "Workaround removed; billion-context is back to its default",
  "已知问题：Claude 5.x 压缩后永久 400": "Known issue: permanent 400 on Claude 5.x after compression",
  "用 Claude 5.x（Opus / Sonnet 5.5、Fable、Mythos）时，billion-context 的一次压缩可能把同一条回复里的思考块和工具调用拆开，之后这个会话每次都报「thinking blocks … cannot be modified」，只能换模型。下面的绕法把 compress.neverPreserveRecentTools 设为 []：压缩不再挖进最近保护区，代价是刚读的 bash / read 结果要晚几轮才能被压缩。已经报错的会话修不回来，换模型或开新会话。": "With Claude 5.x (Opus / Sonnet 5.5, Fable, Mythos), one billion-context compression can split a reply's thinking blocks from its tool calls; from then on every request in that session fails with \"thinking blocks … cannot be modified\" and only switching models helps. The workaround sets compress.neverPreserveRecentTools to []: compression no longer cuts into the recent protected zone, at the cost of fresh bash / read results becoming compressible a few turns later. Sessions that already fail cannot be repaired; switch models or start a new session.",
  "上游问题：": "Upstream issue: ",
  "现在：未应用（用 billion-context 的默认）": "Now: not applied (billion-context default)",
  "现在：已应用": "Now: applied",
  "现在：文件里自定义为 {p1}，点「应用」会改成 []": "Now: the file sets it to {p1}; Apply changes it to []",
  "撤销绕法": "Remove workaround",
  "应用绕法": "Apply workaround",
  "装了 billion-context 的话，这是它的已知问题：压缩拆开了带签名的思考块，重试不会好。换个模型就能接着聊；到「设置 → 子代理 → acp_delegate」点「应用绕法」可以避免以后再出现。": "If billion-context is installed, this is a known issue of it: a compression split signed thinking blocks, so retrying won't help. Switch models to keep chatting; Settings → Subagent → acp_delegate → Apply workaround prevents it from happening again.",
  // -- 预览里的翻译对照（D245）
  "翻译对照：翻成别的语言，左右对着看": "Translation compare: translate into another language and read both side by side",
  "只有 md / text 能翻译": "Only md / text can be translated",
  "超过 512 KB，不在预览里翻": "Over 512 KB — too large to translate here",
  "翻译成什么？用什么翻？": "Translate into what, with which model?",
  "默认用一个便宜的模型就够了：翻文档不需要最强的那个。译文只存在本机。": "A cheap model is usually enough — documents don't need the strongest one. The translation stays on this machine.",
