  "正在翻 {n} 块": "{n} blocks in flight",
  "同时翻几块": "Blocks in parallel",
  "每个往返的固定等待（起进程 + 等模型开口）跟正文长短无关，所以几块一起翻才快；撞到模型限流会自动降并发、退避重发。": "Each round trip has a fixed wait (spawn plus time-to-first-token) that barely depends on the text, so several blocks in flight is what makes it fast. Hitting a rate limit automatically lowers the concurrency and retries after a backoff.",
  "以后同时翻 {n} 块": "{n} blocks will be translated in parallel",
  "翻译失败了": "Translation failed",
  "原文改过了，点「更新」只重翻变了的节": "The source changed — hit Update to re-translate only what changed",
  "译文是 {p1} 生成的": "Translated by {p1}",
  "{n} 节没翻成，点「更新」重翻": "{n} section(s) failed — hit Update to retry",
  "这一节没翻成，原文留下了；点「更新」重翻": "This section failed, so the original was kept; hit Update to retry",
  "这一节你改过": "You edited this section",
