  "这个模型现在不在模型目录里（{p1}），下次翻译会先让你挑一个。": "That model is not in the catalogue right now ({p1}); the next translation will ask you to pick one.",
  "预览右上角的「译」会用这里选的模型：另起一个 pi 子进程翻，不占当前对话的上下文。译文只存在本机，原文不动；在对照里改的译文可以再写回原文。": "The 译 button in the preview uses this model: a separate pi child process does the translating, so it does not use up this conversation's context. Translations stay on this machine and the source is untouched; edits you make in the comparison can be written back to the source.",
  "换模型不会重翻已有的译文：点「更新」时才按新模型整篇重来。": "Switching the model does not re-translate existing output; press Update to redo the whole document with the new model.",
  "没找到默认的翻译模型 {p1}，挑一个：以后就用这个。": "The default translation model {p1} was not found here; pick one — it becomes the default.",
  "默认用便宜的模型就够了：翻文档不需要最强的那个。这次选的会记住。": "A cheap model is enough: translating documents does not need the strongest one. This choice will be remembered.",
