  "上下文用到窗口的这个百分比就自动压缩；夹在 5–90%，不会越过 pi 自己的压缩线。会话级覆盖在上下文面板的「自动压缩」里改（#484）": "Compact once the context reaches this share of the window; clamped to 5–90% and kept below pi's own compaction line. Per-session overrides live in the context panel's “Auto-compact” (#484)",
  "与自动压缩至少差 5 个百分点；两条不能相同（同一时间只执行其中一个）": "Must sit at least 5 points away from auto-compact; the two cannot be equal (only one runs at a time)",
  "两条阈值不能相同：同一时间只能执行其中一个": "The two thresholds cannot be equal: only one of them runs at a time",
  "两条阈值至少要差 5 个百分点": "The two thresholds must differ by at least 5 points",
  "交接": "Handoff",
  "交接 = 把这一摊现场写成交接文档，再开一个同目录的新会话读它继续。旧会话会停下并归档，翻回去只是读历史。": "Handoff writes the current state into a handoff document, then opens a new session in the same folder that reads it and continues. The old session stops and is archived; browsing it back is read-only history.",
  "交接完成，已切到新会话": "Handoff complete — switched to the new session",
  "交接已开始：正在中断并生成交接文档…": "Handoff started: interrupting and writing the handoff document…",
  "交接没有完成：{p1}": "Handoff did not finish: {p1}",
  "到阈值时停下来写交接文档，再开一个同目录的新会话接着做；关着不影响手动交接": "At the threshold it stops, writes a handoff document and continues in a new session in the same folder; leaving it off does not affect manual handoff",
  "已保存会话级阈值": "Saved session thresholds",
  "已开启：{p1}": "On: {p1}",
  "当前会话": "This session",
  "当前模型窗口 {p1}：两条线都按它的百分比算，且不会越过 pi 自己的压缩线。": "Model window {p1}: both lines are percentages of it and never cross pi's own compaction line.",
  "恢复跟随": "Follow again",
  "手动交接": "Hand off now",
  "手动交接：停当前任务 → 生成交接文档 → 新会话读文档继续。自动交接：上下文到阈值时自动做同一件事（可以连着交接多轮）。": "Manual: stop the current task → write the handoff document → a new session reads it and continues. Automatic: the same thing happens when the context reaches the threshold (can chain as often as needed).",
  "把现场写成交接文档，在新会话里继续": "Write the current state into a handoff document and continue in a new session",
  "按窗口百分比设置自动压缩 / 自动交接的阈值": "Set the auto-compact / auto-handoff thresholds as a share of the window",
